  mix-blend-mode: multiply;
}
#grain {
  position: absolute; inset: -60px; pointer-events: none; z-index: 3; opacity: .14;
  background-repeat: repeat; animation: grainShift .55s steps(3) infinite;
  mix-blend-mode: overlay;
}
@keyframes grainShift {
  0% { transform: translate(0,0); } 33% { transform: translate(-18px, 11px); } 66% { transform: translate(12px, -16px); } 100% { transform: translate(0,0); }
}
#flash {
  position: absolute; inset: 0; z-index: 30; pointer-events: none; background: #fff; opacity: 0;
}
#flash.go { animation: flashOut .5s ease-out; }
