.obj-label { display: block; font-size: 8px; letter-spacing: .34em; color: var(--rust-hot); margin-bottom: 5px; }
#objectiveText { display: block; font-family: 'Bebas Neue'; font-size: clamp(19px, 2.3vw, 28px); letter-spacing: .07em; line-height: 1.05; }
