.hud-bottom {
  position: absolute; left: clamp(18px, 3.6vw, 54px); right: clamp(18px, 3.6vw, 54px); bottom: calc(22px + var(--safe-bottom));
  display: flex; justify-content: space-between; align-items: flex-end; gap: 16px;
}
.controls-hint { display: flex; flex-wrap: wrap; gap: 16px; opacity: .78; text-shadow: 0 1px 5px #000; }
.controls-hint span { font-size: 7.5px; letter-spacing: .14em; color: rgba(236,230,214,.7); display: flex; align-items: center; gap: 5px; }
kbd {
  display: inline-flex; align-items: center; justify-content: center; min-width: 20px; height: 20px; padding: 0 5px;
  font-family: 'Manrope'; font-size: 8px; font-weight: 800; letter-spacing: .06em; color: #e9e1cd;
  background: rgba(16,19,14,.68); border: 1px solid rgba(236,230,214,.26); border-radius: 3px;
  box-shadow: 0 2px 0 rgba(0,0,0,.4); backdrop-filter: blur(4px);
}
#crouchHint { transition: opacity .3s, color .3s; }
#crouchHint.glow { color: #fff; animation: hintPulse 1.2s ease-in-out infinite; }
#crouchHint.glow kbd { border-color: var(--rust); color: var(--rust-hot); }
@keyframes hintPulse { 50% { opacity: .5; } }
.hud-status { display: flex; align-items: center; gap: 8px; font-size: 7.5px; letter-spacing: .24em; color: rgba(236,230,214,.44); text-shadow: 0 1px 5px #000; }
.hud-status .heart { width: 7px; height: 7px; background: var(--rust); border-radius: 50%; box-shadow: 0 0 10px rgba(201,104,60,.6); animation: heartBeat 2.4s ease-in-out infinite; }
@keyframes heartBeat { 0%,100% { opacity: .45; transform: scale(.85); } 8% { opacity: 1; transform: scale(1.15); } 16% { opacity: .6; transform: scale(.95); } 24% { opacity: .9; transform: scale(1.05); } }
.look-hint {
  position: absolute; left: 50%; bottom: calc(72px + var(--safe-bottom)); transform: translateX(-50%);
  font-size: 8px; letter-spacing: .24em; color: rgba(236,230,214,.52); padding: 9px 16px;
  border: 1px solid rgba(236,230,214,.14); background: rgba(5,7,5,.42); backdrop-filter: blur(6px);
  transition: opacity .4s; white-space: nowrap;
}
.look-hint span { color: var(--rust); margin: 0 6px; }
.look-hint.hide { opacity: 0; }
.interact-prompt {
  position: absolute; left: 50%; top: 58%; transform: translateX(-50%); display: flex; align-items: center; gap: 8px;
  font-size: 9px; letter-spacing: .24em; color: #eee5d1; padding: 9px 14px; background: rgba(6,8,6,.62);
  border: 1px solid rgba(236,230,214,.2); backdrop-filter: blur(6px); animation: promptIn .3s ease-out;
}
