.tut-copy p { margin: 8px 0 0; font-size: 10px; line-height: 1.6; color: var(--bone-dim); }
.tut-copy b { color: var(--bone); }
.tut-bar { position: absolute; left: 0; right: 0; bottom: 0; height: 2px; background: rgba(236,230,214,.08); }
.tut-bar i { display: block; height: 100%; width: 100%; background: var(--rust); transform-origin: left; animation: tutTime 7s linear forwards; }
@keyframes tutTime { to { transform: scaleX(0); } }

/* mobile */
