.opt-row .val { width: 30px; text-align: right; font-size: 10px; color: var(--bone-dim); }
.switch { position: relative; width: 44px; height: 22px; border: 1px solid rgba(236,230,214,.3); background: rgba(236,230,214,.06); cursor: pointer; }
