import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const OUT = '/tmp/opencode/shots';
import { mkdirSync } from 'node:fs';
mkdirSync(OUT, { recursive: true });

const browser = await chromium.launch({ args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = [];
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message + '\n' + (e.stack || '')));

await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'load' });
await page.waitForTimeout(2200);
await page.screenshot({ path: `${OUT}/01-menu.png` });
console.log('mode', await page.evaluate(() => window.__lastCan?.mode));

await page.click('#playBtn');
await page.waitForTimeout(2500);
await page.screenshot({ path: `${OUT}/02-cutscene.png` });

// skip to game
await page.evaluate(() => window.__lastCan.director.skip());
await page.waitForTimeout(2500);
await page.screenshot({ path: `${OUT}/03-lot.png` });
console.log('after skip mode', await page.evaluate(() => window.__lastCan.mode), 'phase', await page.evaluate(() => window.__lastCan.game?.phase));

// force store
await page.evaluate(() => window.__lastCan.game.enterStore('shoot'));
await page.waitForTimeout(3500);
await page.screenshot({ path: `${OUT}/04-store.png` });

// move near a can and take it
const canInfo = await page.evaluate(() => {
  const g = window.__lastCan.game;
  const can = g.interior.cans.find(c => !c.userData.taken);
  g.player.position.set(can.position.x, 0, can.position.z + 0.6);
  return { name: can.userData.name, x: can.position.x, z: can.position.z };
});
await page.waitForTimeout(400);
console.log('can', canInfo);
await page.evaluate(() => window.__lastCan.game.interact());
await page.waitForTimeout(800);
await page.screenshot({ path: `${OUT}/05-can.png` });
console.log('cansFound', await page.evaluate(() => window.__lastCan.game.cansFound));

// keypad
await page.evaluate(() => window.__lastCan.game.openKeypad());
await page.waitForTimeout(600);
await page.screenshot({ path: `${OUT}/06-keypad.png` });
for (const d of '261212') await page.evaluate((d) => window.__lastCan.game.pressKeypad(d), d);
await page.waitForTimeout(1200);
console.log('keypadUnlocked', await page.evaluate(() => window.__lastCan.game.keypadUnlocked));
await page.screenshot({ path: `${OUT}/07-fuel-open.png` });

// standoff
