cabLight.position.set(0.1, 1.82, 0.05); scene.add(cabLight);
const dashLight = new THREE.PointLight(0xff9b52, 3, 2.4, 2);
dashLight.position.set(-0.45, 1.3, 1.0); scene.add(dashLight);
const gaugeMat = new THREE.MeshStandardMaterial({ color: 0x0d1712, emissive: 0x4dff9a, emissiveIntensity: 0.9, roughness: 0.4 });
cab.add(box(0.44, 0.13, 0.03, gaugeMat, -0.58, 1.19, 1.36));
cab.add(box(0.12, 0.05, 0.02, new THREE.MeshStandardMaterial({ color: 0x2a0d08, emissive: 0xff3a1a, emissiveIntensity: 1.2 }), 0.0, 1.26, 1.52));
// windshield glass
const windshield = new THREE.Group();
const windMat = new THREE.MeshPhysicalMaterial({ color: 0x9fb2a9, transparent: true, opacity: mode === 'start' ? 0.16 : 0.1, roughness: 0.05, metalness: 0.2, side: THREE.DoubleSide, depthWrite: false });
const wind = plane(2.02, 0.82, windMat, 0, 1.55, 1.62);
wind.rotation.x = -0.28;
windshield.add(wind);
const crackMat = new THREE.MeshBasicMaterial({ map: crackTexture(3), transparent: true, opacity: 0, depthWrite: false, side: THREE.DoubleSide });
const cracks = plane(1.95, 0.8, crackMat, 0, 1.56, 1.63);
cracks.rotation.x = -0.28;
windshield.add(cracks);
scene.add(windshield);

// driver side window glass
const sideGlassMat = new THREE.MeshPhysicalMaterial({ color: 0x8fa49b, transparent: true, opacity: 0.13, roughness: 0.06, metalness: 0.2, side: THREE.DoubleSide, depthWrite: false });
const sideGlass = plane(0.94, 0.5, sideGlassMat, -1.075, 1.42, 0.1);
sideGlass.rotation.y = -Math.PI / 2;
scene.add(sideGlass);

// side mirror / exterior details
scene.add(box(0.16, 0.26, 0.1, MAT.darkMetal, -1.25, 1.4, 0.62));
scene.add(box(0.1, 0.2, 0.4, MAT.darkMetal, -1.12, 1.46, 1.3));

// headlight beams
const beams = [];
for (const s of [-1, 1]) {
  const spot = new THREE.SpotLight(0xffdcaa, mode === 'drive' ? 160 : 0, 60, 0.5, 0.55, 1.3);
  spot.position.set(s * 0.7, 0.2, 4.2);
  spot.target.position.set(s * 0.9, -1.5, 36);
  scene.add(spot, spot.target);
  beams.push(spot);
  const glow = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTexture('rgba(255,230,180,1)', 'rgba(255,180,80,0)'), transparent: true, opacity: mode === 'drive' ? 0.55 : 0, depthWrite: false, blending: THREE.AdditiveBlending }));
  glow.position.set(s * 0.7, 0.25, 4.3); glow.scale.set(2.6, 2.6, 1); scene.add(glow);
}
// hood
scene.add(box(2.05, 0.14, 2.0, new THREE.MeshStandardMaterial({ color: 0x4a564d, roughness: 0.7, metalness: 0.3 }), 0, 0.55, 4.4));
const hoodGlow = new THREE.PointLight(0xffcf9a, 2.4, 7, 2);
hoodGlow.position.set(0, 0.9, 3.2); scene.add(hoodGlow);

// Tim in the driver seat
const tim = new TimCharacter();
tim.setSeated(true);
tim.group.position.set(-0.55, 0.03, -0.02);
tim.group.rotation.y = 0;
tim.body.position.y = 0.1;
tim.parts.torso.rotation.x = 0.12;
tim.parts.head.rotation.x = -0.02;
scene.add(tim.group);
// hands on the wheel
const wheelPose = () => {
  tim.parts.armL.shoulder.rotation.x = -1.18;

  let started = false;
  for (let attempt = 0; attempt < 3 && !started; attempt++) {
    const ok = await this.runQTE({
      mode: 'swipeDown',
      kicker: 'THE IGNITION',
      title: 'AGAIN — TURN IT',
      hint: 'Swipe down — or press ↓ — hard.',
      target: 1,
      duration: 5,
      glyph: '↓',
    });
    if (ok) {
      started = true;
      this.truck.startEngine();
      audio.tone({ freq: 58, dur: 2.0, gain: 0.16, type: 'sawtooth', slide: 0.4 });
      this.callbacks.onFlash?.();
      this.caption('TIM', 'Yes! YES!', 1.8);
      this.cameraShake = 0.12;
    } else {
      this.caption('TIM', 'Not now. Not now!', 1.6);
    }
  }
  if (!started) {
    this.truck.startEngine();
    this.caption('TIM', 'GO!', 1.2);
  }
  await this.wait(1.4);

  this.truck.attack(-1);
  this.callbacks.onFlash?.();
  this.cameraShake = 0.24;
  this.caption('', 'A shotgun blast took the mirror off.', 2.4);
  await this.wait(1.2);
  this.truck.breakSideGlass();
  this.cameraShake = 0.26;
  this.caption('', 'Glass sprayed across the cab.', 2.2);
  await this.wait(1.2);
  this.truck.attack(1);
  this.truck.hitWindshield(0.5);
  this.caption('MACE', 'JAAKE! STOP HIM!', 2.2);
  await this.wait(1.3);
  this.caption('', 'A tire blew. The wheel went light in his hands.', 2.6);
  this.truck.setShake(0.34);
  audio.shot();
  await this.wait(1.4);

  this.truck.crash();
  audio.roar();
  audio.sting();
  this.callbacks.onFlash?.();
  this.cameraShake = 0.5;
  this.caption('', 'The road turned sideways.', 2.4);
  await this.wait(2.4);
  this.callbacks.onFade?.(1);
  await this.wait(1.2);
  this.finish({
    choice: this.branch,
    statChoice: this.chaseChoice || this.branchLabel || 'RAN',
    title: 'THE LAST CAN',
    copy: 'The truck left the road and the dark came through the windshield. Chapter One ends here — but something in Homewood heard the crash.',
    remembered: 'THE DEAD WILL REMEMBER THAT',
    cans: `${this.cansFound} CAN${this.cansFound === 1 ? '' : 'S'} FOUND`,
  });
}

/* ------------------------------ helpers ------------------------------ */
interact() {
  if (this.phase === 'store' && this.state === 'active') { this.interactStore(); return; }
  if (this.phase !== 'lot') return;
  if (this.branch === 'side' && this.state === 'active') {
    const p = this.player.position;
    if (Math.hypot(p.x - this.compound.ventTrigger.x, p.z - this.compound.ventTrigger.z) < 3.6) {
      this.startVentSequence();
    }
  }
}

interactStore() {
  const f = this.storeFocus;
  if (!f) return;
  if (f.kind === 'can') {
    if (!this.interior.takeCan(f.target)) return;
    this.cansFound++;
    audio.canOpen();
    this.updateCanHud(true);
    this.caption('TIM', f.target.userData.name.charAt(0) + f.target.userData.name.slice(1).toLowerCase() + '. Still good. Probably.', 2.4);
    if (this.cansFound >= this.totalCans) {
      this.callbacks.onObjective?.('THE FUEL ROOM', 'The code is written on the wall. Find it.');
      this.interior.showKeyMarker(true);
      this.caption('TIM', 'That\'s ten. Now the fuel.', 3.0);
      audio.heartbeat();
    } else {
      this.callbacks.onObjective?.('SEARCH THE STORE', `${this.cansFound} of ${this.totalCans} cans found.`);
    }
    return;
  }
  if (f.kind === 'note') { this.showNote(); return; }
  if (f.kind === 'blood') {
    this.sawBlood = true;
    this.callbacks.onObjective?.('THE FUEL ROOM', 'Enter the build date: last two digits of year, day, month.');
    this.caption('', 'BUILD IN 12/12/1926. The paint had run like it was crying.', 3.6);
    this.interior.showKeyMarker(true);
    audio.heartbeat();
    return;
  }
  if (f.kind === 'keypad') { this.openKeypad(); return; }
  if (f.kind === 'fuel') { this.startStandoff(); return; }
  if (f.kind === 'locker') {
    this.caption('TIM', 'A locker. Heavy. Probably empty.', 2.4);
    return;
  }
}

