    const sy = Math.sin(this.yaw), cy = Math.cos(this.yaw);
    const desired = new THREE.Vector3(
      p.x + sy * hd + cy * 0.7,
      p.y + targetY + 0.9 + Math.sin(this.pitch) * 2.4,
