  await this.tween(2.0, (u) => {
    p.y = 2.8 - u * 0.4;
    p.x = -24.1 + u * 2.2;
    p.z = -26.7;
    this.player.rotation.y = Math.PI / 2;
    this.tim.setCrouch(1);
    this.tim.setLocomotion(0.5, 1 / 60);
    this.tim.update(1 / 60);
    this.camera.position.lerp(new THREE.Vector3(-23.4 + u * 2.4, 2.9, -25.6), 0.05);
