457: function frame(now) {
458:   const dt = Math.min(0.05, Math.max(0.0001, (now - lastTime) / 1000));
459:   lastTime = now;
460: 
461:   if (mode === 'cutscene') {
462:     director.update(dt);
463:     const scene = director.current?.scene;
464:     const camera = director.current?.camera;
465:     if (scene && camera) renderer.render(scene, camera);
466:   } else if (mode === 'game' && game?.scene && game?.camera) {
467:     game.update(dt);
468:     renderer.render(game.scene, game.camera);
469:   } else if (mode === 'menu' || mode === 'loading') {
470:     menuTime += dt;
471:     menuWorld.update(dt, menuTime);
472:     renderer.render(menuScene, menuWorld.camera);
473:   } else if (mode === 'end' && game?.scene && game?.camera) {
474:     // keep the last frozen frame behind the end card
